function Badge({children,color='mint'}){return <span className={'badge '+color}>{children}</span>}
function AdBanner({placement='global',city=''}) {
 const [campaign,setCampaign]=useState(null);
 const [fallback,setFallback]=useState('none');
 const [adConfig,setAdConfig]=useState(null);
 React.useEffect(()=>{let cancelled=false;const params=new URLSearchParams({placement,city});fetch('/api/ads?'+params.toString(),{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(cancelled||!data)return;setCampaign(data.ad||null);setFallback(data.fallback||'none');setAdConfig(data.clientId&&data.slot?{clientId:data.clientId,slot:data.slot}:null);}).catch(()=>{});return()=>{cancelled=true};},[placement,city]);
 React.useEffect(()=>{if(fallback!=='google'||!adConfig)return;const scriptId='morotto-adsense-script';if(!document.getElementById(scriptId)){const script=document.createElement('script');script.id=scriptId;script.async=true;script.crossOrigin='anonymous';script.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+encodeURIComponent(adConfig.clientId);document.head.appendChild(script);}try{window.adsbygoogle=window.adsbygoogle||[];window.adsbygoogle.push({});}catch(error){console.warn('AdSense slot could not initialize:',error);} },[fallback,adConfig]);
 if(campaign)return <a className="adbanner adbanner-managed" href={campaign.click_url||'#'} target="_blank" rel="sponsored noopener noreferrer"><div className="adicon">{campaign.image_url?<img src={campaign.image_url} alt="" loading="lazy"/>:<Sparkles size={19}/>}</div><div><small>PARTENAIRE · {campaign.advertiser_name}</small><b>{campaign.title}</b><p>{campaign.body}</p></div><span className="adlink">Découvrir <ArrowRight size={15}/></span></a>;
 if(fallback==='google'&&adConfig)return <div className="adbanner adbanner-google" aria-label="Publicité"><small>PUBLICITÉ</small><ins className="adsbygoogle" style={{display:'block',minHeight:'90px'}} data-ad-client={adConfig.clientId} data-ad-slot={adConfig.slot} data-ad-format="auto" data-full-width-responsive="true"/></div>;
 return <div className="adbanner"><div className="adicon"><Sparkles size={19}/></div><div><small>ESPACE PARTENAIRE</small><b>Votre prochaine route commence ici.</b><p>Découvrez les offres de nos partenaires mobilité.</p></div><button className="adlink" onClick={()=>window.dispatchEvent(new CustomEvent('tab',{detail:'pro'}))}>En savoir plus <ArrowRight size={15}/></button></div>;
}
function VehicleCard({v,onDetails,favorite,isFav}){return <article className="vehicle-card"><div className="vehicle-photo">{v.demo ? <VehiclePhoto brand={v.brand} model={v.model} year={v.year} listingId={v.id} alt={`${v.brand} ${v.model}, ${v.year}, démonstration`}/> : <img src={v.image} alt={v.brand+' '+v.model} loading="lazy" onError={e=>{e.currentTarget.onerror=null;e.currentTarget.src='https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=900&q=80';}}/>}<span className="photo-tag">{v.type}</span><button className={'fav '+(isFav?'active':'')} aria-label="Ajouter aux favoris" onClick={()=>favorite(v.id)}><Heart size={17} fill={isFav?'currentColor':'none'}/></button></div><div className="vehicle-info"><div className="vehicle-meta"><span>{v.brand}</span><span>{v.year}</span></div><h3>{v.model}</h3><div className="vehicle-spec"><span><Fuel size={14}/>{v.fuel}</span><span><Gauge size={14}/>{v.cv} CV</span><span><Route size={14}/>{(v.mileage/1000).toFixed(0)}k km</span></div><div className="vehicle-bottom"><b>{fmt(v.price)}</b><button className="circle-button" onClick={()=>onDetails(v)} aria-label="Voir le véhicule"><ArrowUpRight size={17}/></button></div><div className="vehicle-city"><MapPin size={13}/>{v.city}, Maroc</div></div></article>}
